BEGIN READ ONLY;SET LOCAL statement_timeout='10s'; SET LOCAL search_path TO adempiere,pg_catalog;
SELECT json_agg(row_to_json(q)) FROM (SELECT ad_menu_id,name as name_en,name as name_loc,true as is_translated,NULL as description,action,ad_window_id,ad_process_id,ad_form_id,ad_workflow_id,ad_task_id,ad_workbench_id,ad_infowindow_id,name as object_name,null as primary_table,isactive,issummary FROM ad_menu WHERE isactive='Y' AND action IN ('F','X') ORDER BY ad_menu_id) q;
ROLLBACK;
